#include <bits/stdc++.h>

using namespace std;

const int MAX_SIZE = 2345678;

double prob_real[123], prob[123];
double dp_array[MAX_SIZE];
double result_arr[123];
int idx[123];
int bits_count[MAX_SIZE];

int main() {
    int total_real, max_k_value;
    scanf("%d %d", &total_real, &max_k_value);
    int valid_count = 0;
    for (int i = 0; i < total_real; i++) {
        scanf("%lf", prob_real + i);
        if (prob_real[i] > 1e-4) {
            idx[valid_count] = i;
            prob[valid_count] = prob_real[i];
            valid_count++;
        }
    }
    max_k_value = min(max_k_value, valid_count);
    bits_count[0] = 0;
    for (int mask = 1; mask < (1 << valid_count); mask++) {
        bits_count[mask] = bits_count[mask & (mask - 1)] + 1;
    }
    for (int mask = 0; mask < (1 << valid_count); mask++) {
        dp_array[mask] = 0.0;
    }
    for (int i = 0; i < total_real; i++) {
        result_arr[i] = 0.0;
    }
    dp_array[0] = 1.0;
    for (int mask = 0; mask < (1 << valid_count); mask++) {
        if (bits_count[mask] == max_k_value) {
            for (int j = 0; j < valid_count; j++) {
                if (mask & (1 << j)) {
                    result_arr[idx[j]] += dp_array[mask];
                }
            }
            continue;
        }
        double total_prob = 0;
        for (int j = 0; j < valid_count; j++) {
            if (mask & (1 << j)) continue;
            total_prob += prob[j];
        }
        double ratio = dp_array[mask] / total_prob;
        for (int j = 0; j < valid_count; j++) {
            if (mask & (1 << j)) continue;
            dp_array[mask | (1 << j)] += prob[j] * ratio;
        }
    }
    for (int i = 0; i < total_real; i++) {
        if (i > 0) cout << " ";
        printf("%.17f", result_arr[i]);
    }
    printf("\n");
    return 0;
}
